package com.example.todo.service; import com.example.todo.dto.*; import com.example.todo.entity.User; import com.example.todo.repository.UserRepository; import com.example.todo.security.JwtService; import lombok.RequiredArgsConstructor; import org.springframework.security.authentication.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; @Service @RequiredArgsConstructor public class AuthService {private final UserRepository repo;private final PasswordEncoder enc;private final AuthenticationManager auth;private final JwtService jwt; public AuthResponse register(AuthRequest r){if(repo.existsByUsername(r.username()))throw new IllegalArgumentException("Username already exists");User u=repo.save(User.builder().username(r.username()).password(enc.encode(r.password())).build());return new AuthResponse(jwt.generateToken(u.getUsername()),u.getUsername());} public AuthResponse login(AuthRequest r){auth.authenticate(new UsernamePasswordAuthenticationToken(r.username(),r.password()));return new AuthResponse(jwt.generateToken(r.username()),r.username());}}
